package tp.cache.js5

/**
 * Expected master-index facts for OpenRS2 cache 2757 (oldschool/live/en, build 242, captured 2026-11-03).
 * Source: https://archive.openrs2.org/caches/runescape/2757 — values recorded in docs/BRIEF.md §1.
 * Phase 5 moves these into per-revision config generated by `upgradeRevision`.
 */
object CacheSpotChecks {
    private const val ARCHIVES = 25
    private const val GROUPS = 120_374

    private data class Expect(val archive: Int, val version: Int, val crc: Int)

    private val expected =
        listOf(
            Expect(archive = 0, version = 1_793_635_657, crc = 1_319_971_744),
            Expect(archive = 24, version = 1, crc = -1_931_708_361),
        )

    /**
     * Returns true when every check passes; each failure is reported through [report]. A packed cache (tools/cache-pack,
     * D-071) adds groups to archives 2 / 3 / 12 only, so it passes its own [groups] count (from its `pack.properties`).
     */
    fun verify(cache: Js5Cache, groups: Int = GROUPS, report: (String) -> Unit): Boolean {
        var ok = true

        fun fail(msg: String) {
            ok = false
            report(msg)
        }
        if (cache.archiveCount != ARCHIVES) fail("archive count ${cache.archiveCount}, expected $ARCHIVES")
        if (cache.groupCount != groups) fail("group count ${cache.groupCount}, expected $groups")
        for (e in expected) {
            val info = cache.archive(e.archive)
            when {
                info == null -> fail("archive ${e.archive} missing from master index")
                info.version != e.version -> fail("archive ${e.archive} version ${info.version}, expected ${e.version}")
                info.crc != e.crc -> fail("archive ${e.archive} CRC ${info.crc}, expected ${e.crc}")
            }
        }
        return ok
    }
}
